       t.det || jsonb_build_object('svcId', (select i.id from items i where i.business_id = 'atencion-inmediata-santa-clara-hazleton' and i.module = 'svc' and i.sort = t.it)::text), t.sub, t.tot, t.dep, t.pay, t.ps, case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end, case when t.ans is not null then (t.ans::timestamp at time zone 'America/New_York') when t.ansm is not null then (case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end) + t.ansm * interval '1 minute' end, case when t.st in ('confirmed', 'done') then case when t.ans is not null then (t.ans::timestamp at time zone 'America/New_York') when t.ansm is not null then (case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end) + t.ansm * interval '1 minute' end end,
