select 'C-' || nextval('operations_appt_seq'), t.kind, 'alw', 'clinica-de-urgencias-el-buen-pastor-allentown', (select u.id from users u where u.phone = t.u), case when t.m is null then null else md5(t.m)::uuid end, t.st, t.sd, case when t.rel is not null then ((((now() at time zone 'America/New_York')::date + t.rel) + t.tm::time) at time zone 'America/New_York') else (t.loc::timestamp at time zone 'America/New_York') end, t.dur, t.buf,
       t.det || jsonb_build_object('svcId', (select i.id from items i where i.business_id = 'clinica-de-urgencias-el-buen-pastor-allentown' and i.module = 'svc' and i.sort = t.it)::text), t.sub, t.tot, t.dep, t.pay, t.ps, case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end, case when t.ans is not null then (t.ans::timestamp at time zone 'America/New_York') when t.ansm is not null then (case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end) + t.ansm * interval '1 minute' end, case when t.st in ('confirmed', 'done') then case when t.ans is not null then (t.ans::timestamp at time zone 'America/New_York') when t.ansm is not null then (case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end) + t.ansm * interval '1 minute' end end,
